import {roleExperience,canCreateCourse,canReserve,canViewService,canViewTicket,requireAction} from './role-access.js';
import {usagePage} from './usage.js';
import {roles,uid,today,stamp,searchResources,createTicket,transition,reserve,cancelReservation,citation,outline,outlineFields,migrateRoles} from './domain.js';
import {services,legacy,resources,knowledge,toolGroups,events,initialState,referenceUrl} from './data.js';
import {originalLinks,donationInstructions} from './original-links.js';
import {originalGroups,originalCatalog} from './original.js';
const KEY='nanyong-library-workbench-v2';let state,storageError='';
try{const raw=localStorage.getItem(KEY);state=migrateRoles(raw?JSON.parse(raw):initialState());if(state.version!==1||!Array.isArray(state.tickets)||!Array.isArray(state.projects)||!roles[state.role])throw Error('数据格式不匹配');}catch{state=initialState();storageError='本地数据无法读取，已载入临时初始数据。可导出当前数据后重置。';}
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',book:'M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2ZM12 6v15',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',calendar:'M4 5h16v16H4ZM4 10h16M8 2v6M16 2v6',file:'M5 2h10l4 4v16H5ZM14 2v5h5M8 12h8M8 16h8',message:'M3 3h18v14H9l-6 4ZM7 7h10M7 12h7',arrow:'M4 12h16M14 6l6 6-6 6',folder:'M2 6h8l2 3h10v12H2ZM2 6V3h7l3 3',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',pen:'m4 16 12-12 4 4L8 20l-5 1ZM13 7l4 4',check:'m4 12 5 5L21 5',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM4 22v-3c0-6 16-6 16 0v3',download:'M12 2v13m-5-5 5 5 5-5M3 16v6h18v-6',layers:'m12 2 10 5-10 5L2 7Zm-10 10 10 5 10-5M2 17l10 5 10-5'};
const icon=(n='book')=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const btn=(label,action,id='',kind='')=>`<button class="btn ${kind}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const link=(label,route,kind='text-link')=>`<a class="${kind}" href="#${route}">${label}</a>`;
const originalLink=(name,route,kind='text-link',label=name)=>{const aliases={'研讨间预约':'研讨间预约（校内IP）','查新查引':'科技查新/查收查引','读者荐购':'资源荐购','高校智盟卡':'江苏省高校智盟卡'};const resolved=aliases[name]||name;const item=originalLinks[resolved];if(item?.kind==='content'){const service=originalServices.find(s=>s.name===resolved);return link(label,service?'service/'+service.id:route,kind);}return item?.url?`<a class="${kind}" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer" title="打开原网站">${label}${kind.includes('original-service-link')||kind.includes('card')||kind==='quick'?'':' ↗'}</a>`:link(label,route,kind);};
const badge=(text,color='')=>`<span class="badge ${color}">${esc(text)}</span>`;
const empty=(title,description,action='')=>`<div class="empty">${icon('folder')}<h3>${title}</h3><p>${description}</p>${action}</div>`;
const head=(title,desc,action='')=>`<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const ownProjects=()=>state.projects.filter(p=>p.owner===state.role);const favorites=()=>state.favorites[state.role]||[];
const myTickets=()=>state.tickets.filter(t=>t.owner===state.role);const myReservations=()=>state.reservations.filter(b=>b.owner===state.role);
const getResource=id=>resources.find(r=>r.id===id);const originalServices=originalCatalog(services,legacy);const originalIds=new Set(originalServices.map(x=>x.id));const allServices=[...originalServices,...services.filter(x=>!originalIds.has(x.id)),...legacy.filter(x=>!originalIds.has(x.id))];
let route='home',parts=[],params=new URLSearchParams(),scope=state.role==='alumni'?'services':'resources',toastTimer,searchTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError='';}catch{storageError='浏览器存储不可用或空间不足；当前操作仅暂存内存。请导出本地数据备份。';toast(storageError);}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function go(r){if(location.hash==='#'+r)render();else location.hash=r;}
function modal(title,desc,body,formId='',extra=''){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><p class="modal-desc">${desc}</p>${formId?`<form id="${formId}" ${extra}>`:''}<div class="form-grid">${body}</div><div id="modal-error" class="error hidden" role="alert"></div>${formId?'<div class="modal-actions"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary" type="submit">保存并继续</button></div></form>':''}`;if(!m.open)m.showModal();}
function error(e){const el=$('#modal').open?$('#modal-error'):$('#page-error');if(el){el.textContent=e.message||String(e);el.classList.remove('hidden');el.scrollIntoView({block:'nearest'});}else toast(e.message||String(e));}
function field(label,name,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="300"></label>`;}
function area(label,name,value='',required=true){return `<label>${label}<textarea name="${name}" ${required?'required':''} maxlength="6000">${esc(value)}</textarea></label>`;}
function opts(list,value){return list.map(v=>`<option value="${esc(typeof v==='string'?v.id||v:v[0])}" ${(typeof v==='string'?v:v[0])===value?'selected':''}>${esc(typeof v==='string'?v:v[1])}</option>`).join('');}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('文件已生成，请查看浏览器下载列表');}
function shell(content){const nav=[['home','首页'],['discover','文献服务'],['research','科研服务'],['services','图书馆服务'],['spaces','空间服务'],['help','服务反馈']];let active=route;if(['project','courses','tools'].includes(route))active='research';if(route==='service')active='services';if(route==='resource')active='discover';if(route==='ticket')active='workspace';return `<header class="header"><div class="header-inner"><a href="#home" class="brand" aria-label="南京大学图书馆首页"><img class="library-logo" src="assets/nju-library-logo.png" alt="南京大学图书馆"></a><nav class="nav" aria-label="主导航">${nav.map(([r,n])=>`<a href="#${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="role-wrap"><a href="#workspace" class="help-link">咨询反馈</a><span class="avatar">${roles[state.role][0]}</span><select id="role" aria-label="当前身份">${opts(Object.entries(roles),state.role)}</select></div></div></header><main id="main" class="container" tabindex="-1">${storageError?`<div class="error">${esc(storageError)} ${btn('导出本地数据','export-state','','small')} ${btn('重置','reset','','small')}</div>`:''}<div id="page-error" class="error hidden" role="alert"></div>${content}</main><footer class="footer"><div class="footer-inner"><div><strong>智慧图书馆一体化微服务平台</strong>资源导航 · 文献管理 · 服务协作</div><div>${originalLink('AI馆员','help')}<button class="text-link" data-action="guide">使用帮助</button><button class="text-link" data-action="export-state">导出数据</button><button class="text-link" data-action="reset">清空本地数据</button><p style="margin-top:9px">资料和申请保存在当前浏览器，跨设备不共享。</p></div></div></footer>`;}
function searchForm(q='',target='global'){const label=scope==='resources'?'馆藏搜索':'搜索';return `<form id="search-${target}" class="search-row"><input name="q" aria-label="请输入关键词" placeholder="请输入关键词" value="${esc(q)}"><button class="btn primary" type="submit">${icon('search')} ${label}</button></form>`;}
function ticketRows(list){return list.length?list.slice(0,4).map(t=>`<a class="list-row" href="#ticket/${t.id}"><span class="status-dot"></span><div class="grow"><h3>${esc(t.title)}</h3><p>${t.no} · ${esc(t.type)}</p></div>${badge(t.status,t.status==='待补材料'?'orange':t.status==='已完成'?'green':'')}</a>`).join(''):`<div class="todo-empty">暂无申请记录。提交后可在此查看办理进度。</div>`;}
function roleServiceLink(name,kind='original-service-link'){const custom={'课程文献中心':'courses','研学助手':'research'};const target=custom[name]||originalGroups.flatMap(g=>g.items).find(x=>x[0]===name)?.[1]||'services?q='+encodeURIComponent(name);return originalLink(name,target,kind,name+' '+icon('arrow'));}
function home(){const profile=roleExperience(state.role);return `<div class="role-home" data-home-role="${state.role}">${profile.landing==='staff'?staffHome(profile):readerHome(profile)}</div>`;}
function readerHome(profile){const hints={resources:'按书名、作者或主题检索文献记录。',services:'按功能名称查找服务入口。',help:'查询馆务指引和常见问题。'};const count=myTickets().filter(t=>t.status!=='已完成').length;return `<section class="hero" aria-label="搜索"><div class="role-home-heading"><h1>${profile.focus}</h1>${badge(roles[state.role],'gray')}</div><div class="searchbox"><div class="search-tabs" role="group" aria-label="搜索范围">${[['resources','馆藏搜索'],['services','图书馆服务'],['help','服务反馈']].map(([k,v])=>`<button data-action="scope" data-id="${k}" class="${scope===k?'active':''}" aria-pressed="${scope===k}">${v}</button>`).join('')}</div>${searchForm()}<p class="search-scope-hint">${hints[scope]}</p><div class="search-footer"><div class="hot">${state.role==='teacher'?link('课程文献中心','courses'):state.role==='alumni'?roleServiceLink('校友云书房','text-link'):link('数字人文','discover?q=数字人文')}${link('人工智能','discover?q=人工智能')}</div>${link(icon('message')+' 使用帮助','usage','btn usage-entry')}</div></div></section>${roleQuick(profile)}<section class="section"><div class="section-head"><h2>${state.role==='teacher'?'科研服务':state.role==='alumni'?'校友/社会公众':'图书馆服务'}</h2>${link('全部服务 →','services')}</div><div class="grid ${profile.sections.length===2?'cols2':'cols3'} home-task-grid">${profile.sections.map(([name,items],i)=>`<article class="card original-service-card"><div class="panel-head"><h3>${name}</h3><div class="mini-icon ${i===1?'green':i===2?'sand':''}">${icon(i===0?'book':i===1?'layers':'calendar')}</div></div><div class="original-link-list">${items.map(n=>roleServiceLink(n)).join('')}</div>${link('更多 →',name==='课程文献中心'?'courses':'services?cat='+encodeURIComponent(name),'text-link original-more')}</article>`).join('')}</div></section><section class="section home-bottom"><div class="card home-pending"><div class="section-head"><h2>${state.role==='teacher'?'课程文献中心':state.role==='alumni'?'咨询反馈':'我的申请'}</h2>${link('查看全部 →',state.role==='teacher'?'courses':'workspace')}</div>${state.role==='teacher'?teacherHomeCourses():ticketRows(myTickets())}<div class="actions">${state.role==='teacher'?btn('创建课程文献中心','new-course','','soft'):btn('咨询留言','consult','','soft')}${link('咨询反馈 →','workspace')}</div></div><div class="card home-card-service"><div class="section-head"><h2>高校智盟卡</h2>${icon('user')}</div><p>跨校服务说明与申领要求以服务入口指南为准。</p><div class="actions">${originalLink('江苏省高校智盟卡','service/n8','btn primary')}</div></div></section><section class="section"><div class="section-head"><h2>${state.role==='teacher'?'研学助手':state.role==='alumni'?'推荐服务':'研学助手'}</h2>${link('更多 →',state.role==='alumni'?'services':'research')}</div><div class="role-resume-grid">${state.role==='alumni'?['校友云书房','南雍撷珍','CADAL数字资源','图书捐赠'].map(n=>roleServiceLink(n)).join(''):ownProjects().length?ownProjects().slice(0,3).map(p=>`<a class="card role-project" href="#project/${p.id}"><h3>${esc(p.title)}</h3><p>${p.refs.length} 篇文献 · ${p.notes.length} 条阅读笔记</p></a>`).join(''):link('研学助手 →','research','card role-project')}</div></section>${feedbackHome()}`;}
function roleQuick(profile){return `<section class="quick-grid" aria-label="常用功能">${profile.shortcuts.map(([i,t,r])=>originalLink(t,r,'quick',icon(i)+'<span>'+t+'</span>')).join('')}</section>`;}
function teacherHomeCourses(){const courses=state.courses.filter(c=>c.owner==='teacher');return courses.length?courses.slice(0,3).map(c=>`<a class="list-row" href="#courses">${icon('book')}<div class="grow"><h3>${esc(c.title)}</h3><p>${c.refs.length} 篇课程文献</p></div>${badge(state.tickets.filter(t=>t.courseId===c.id&&t.status!=='已完成').length+' 项处理中','gray')}</a>`).join(''):'<p class="todo-empty">暂无课程书单。创建课程后，可添加书目并申请馆员补充。</p>';}
function feedbackHome(){return `<section class="section"><div class="section-head"><h2>服务反馈</h2></div><div class="grid cols2">${[['AI馆员','help'],['咨询留言','service/original-consult']].map(([t,r])=>originalLink(t,r,'card original-feedback-card',`<h3>${t} ${icon('arrow')}</h3>`)).join('')}</div></section>`;}
function staffHome(profile){const statuses=['待受理','处理中','待补材料','已回复'];const pending=state.tickets.filter(t=>t.status!=='已完成').sort((a,b)=>statuses.indexOf(a.status)-statuses.indexOf(b.status));return `<section class="staff-home-heading"><div><h1>馆员服务台</h1><p>受理申请、补充材料、回复处理结果。</p></div>${link('查看全部工单 →','workspace','btn primary')}</section><section class="stats staff-home-stats">${statuses.map(s=>`<a class="stat" href="#workspace?status=${encodeURIComponent(s)}"><strong>${state.tickets.filter(t=>t.status===s).length}</strong><span>${s}</span></a>`).join('')}</section>${roleQuick(profile)}<section class="section"><div class="section-head"><h2>服务工单</h2>${link('查看与处理 →','workspace')}</div><div class="card">${pending.length?ticketRows(pending):'<div class="staff-empty"><h3>当前没有待处理工单</h3><p>读者提交的文献申请、咨询和课程补充请求将在这里汇集。</p></div>'}</div></section><section class="section staff-systems"><div class="section-head"><h2>馆员</h2>${link('查看全部 →','services?cat='+encodeURIComponent('馆员'))}</div><div class="grid cols2">${['一体化微服务平台','NLSP'].map(n=>`<article class="card"><h3>${n}</h3><div class="actions">${roleServiceLink(n,'btn soft')}</div></article>`).join('')}</div></section>`;}
function accessDenied(name,description){return `${head(esc(name),'')}<div class="card access-denied"><h2>当前身份无法使用此功能</h2><p>${esc(description)}</p><div class="actions">${link('返回首页','home','btn primary')}${link('查看使用帮助','usage','btn')}</div></div>`;}

function resourceCard(r){const fav=favorites().includes(r.id);return `<article class="card resource-card"><a href="#resource/${r.id}" class="bookcover c${resources.indexOf(r)%3}"><span>${esc(r.title.slice(0,8))}</span></a><div class="resource-main"><div class="row-wrap">${badge(r.type,'gray')}${badge('公开文献','gray')}</div><h3><a href="#resource/${r.id}">${esc(r.title)}</a></h3><p>${esc(r.author)} · ${r.year} · ${esc(r.source)}</p><p>${esc(r.tags.split(' ').join(' / '))}</p><div class="actions">${btn(icon('star')+(fav?'已收藏':'收藏'),'favorite',r.id,fav?'soft small':'small')}${btn('加入文献夹','add-ref',r.id,'small')}${link('详情与获取 →','resource/'+r.id)}</div></div><div class="count">${r.access}</div></article>`;}
function discover(){const tab=params.get('tab')||'resources',q=params.get('q')||'',type=params.get('type')||'全部',year=params.get('year')||'全部';let list=searchResources(resources,q,type,year);if(params.get('fav')==='1')list=list.filter(r=>favorites().includes(r.id));return head('文献服务','检索公开文献，按类型与年份筛选，收藏并加入文献夹。')+`<div class="tabs">${link('资源检索','discover',tab==='resources'?'active':'')}${link('数据库导航','discover?tab=databases',tab==='databases'?'active':'')}${link('数字资源入口','discover?tab=featured',tab==='featured'?'active':'')}</div>`+(tab==='databases'?`<div class="notice">数据库与全文访问由资源提供方认证，请按各网站要求登录。</div><div class="grid cols3">${[['中文学术文献','期刊、学位论文与会议论文','https://www.cnki.net/'],['国际学术文献','引文索引与学术发现','https://www.webofscience.com/'],['国家哲学社会科学文献中心','公开文献发现，具体权限依来源','https://www.ncpssd.cn/'],['CADAL 数字资源','本校原有资源入口，资格待核定','https://www.cadal.edu.cn/'],['开放获取资源','通过来源网站核对全文许可','https://doaj.org/'],['学位论文资源','查看学位论文获取渠道',null]].map(([t,d,url])=>`<div class="card service-card">${badge('外部资源','gray')}<h3>${t}</h3><p>${d}</p>${url?`<a class="text-link" target="_blank" rel="noopener noreferrer" href="${url}">查看外部网站 ↗</a>`:link('查看服务说明 →','service/s41')}</div>`).join('')}</div>`:tab==='featured'?`<div class="grid cols3">${legacy.filter(s=>s.category==='文献服务').map(serviceCard).join('')}</div>`:`<form id="resource-search" class="toolbar"><input name="q" aria-label="资源检索词" placeholder="书名、作者、主题；多个词用空格分隔" value="${esc(q)}"><button class="btn primary">${icon('search')} 检索资源</button></form><div class="resource-layout"><aside class="card filters"><h3>缩小检索范围</h3><form id="resource-filter"><input type="hidden" name="q" value="${esc(q)}"><label>资源类型<select name="type" aria-label="资源类型">${opts(['全部','图书','论文','学位论文','数据集'],type)}</select></label><label>出版时间<select name="year" aria-label="出版时间">${opts([['全部','全部年份'],['2024','2024 年及以后'],['2022','2022 年及以后']],year)}</select></label><label><input type="checkbox" name="fav" ${params.get('fav')==='1'?'checked':''}> 仅我的收藏</label><button class="btn soft">应用筛选</button></form><div class="split-line"></div><p class="count">真实馆藏的可借状态、全文与访问权限，需正式系统接入。</p>${link('没有找到？求助馆员 →','service/s10')}</aside><div><div class="section-head"><span class="count">找到 ${list.length} 条文献${q?' · '+esc(q):''}</span>${link('清除筛选','discover')}</div>${list.length?list.map(resourceCard).join(''):empty('没有找到匹配的公开文献','可输入“城市”“数字人文”，或减少筛选条件。',btn('提交馆际互借与文献传递','request',q,'primary'))}</div></div>`);}
function resourceDetail(id){const r=getResource(id);if(!r)return notFound();return `<div class="breadcrumb">${link('文献服务','discover')} / 资源详情</div><div class="detail-grid"><article class="card detail-content"><div class="resource-detail-top"><div class="bookcover large"><span>${esc(r.title)}</span></div><div>${badge('公开文献','green')}<h1 style="margin-top:15px">${esc(r.title)}</h1><p>${esc(r.originalTitle||r.title)}</p><p>${esc(r.author)} / ${r.year} / ${r.type}</p><p>${esc(r.source)}</p><div class="actions">${btn(favorites().includes(id)?'已收藏':'收藏资源','favorite',id,'soft')}${btn('加入文献夹','add-ref',id)}</div></div></div><h2>资源说明</h2><p>${esc(r.abstract)}</p><h2>获取方式</h2><p>前往来源页面查看全文与发表版本；机构数据库的访问权限以提供方要求为准。</p><div class="actions"><a class="btn primary" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">查看文献来源 ↗</a></div><h2>书目信息</h2><dl class="meta-grid"><div><dt>文献编号</dt><dd>${esc(r.arxivId||r.doi||'待补充')}</dd></div><div><dt>来源</dt><dd>${esc(r.source)}</dd></div><div><dt>原文题名</dt><dd>${esc(r.originalTitle||r.title)}</dd></div><div><dt>作者</dt><dd>${esc(r.author)}</dd></div></dl><p>引用时请核对原文题名、作者和发表版本。</p></article><aside class="card side-card"><h3>收藏、笔记与获取</h3>${btn('馆际互借与文献传递','request-resource',id,'primary')}${btn('保存阅读笔记','note-resource',id)}${btn('导出引用','cite',id)}<p class="aside-note">申请与资料保存在当前浏览器，可在咨询反馈中查看处理记录。正式文献传递请通过服务网站办理。</p></aside></div>`;}
function serviceCard(s){return `<article class="card service-card"><div class="row-wrap">${badge(s.category,'gray')}${badge(s.depth,s.externalUrl?'green':'')}</div><h3>${s.externalUrl?originalLink(s.name,'service/'+s.id,'',esc(s.name)):esc(s.name)}</h3><p>${esc(s.originalLink?.access||s.description)}</p><div class="actions">${s.externalUrl?originalLink(s.name,'service/'+s.id,'text-link','打开服务入口'):''}${link('使用说明 →','service/'+s.id)}</div></article>`;}
function serviceList(){const extended=params.get('source')==='reference';const candidates=extended?services:originalServices.filter(x=>canViewService(state.role,x));const requested=params.get('cat')||'全部',cat=candidates.some(x=>x.category===requested)?requested:'全部',q=params.get('q')||'';const list=candidates.filter(x=>(cat==='全部'||x.category===cat)&&(x.name+' '+x.description).includes(q));return head('图书馆服务','按服务分类或功能名称查找办理入口。')+`<div class="tabs">${link('图书馆服务','services',!extended?'active':'')}${link('更多','services?source=reference',extended?'active':'')}</div>${extended?'<div class="notice">外部服务的适用对象与办理规则以提供方说明为准。</div>':''}<form class="toolbar" id="service-search"><input name="q" value="${esc(q)}" aria-label="请输入功能名称" placeholder="请输入功能名称"><button class="btn primary">搜索</button></form><div class="pills">${['全部',...new Set(candidates.map(x=>x.category))].map(c=>link(c,`services?cat=${encodeURIComponent(c)}&q=${encodeURIComponent(q)}${extended?'&source=reference':''}`,`pill ${c===cat?'active':''}`)).join('')}</div><div class="section-head"><span class="count">${list.length} 项</span>${btn('导出迁移清单','export-catalog','','small')}</div>${list.length?`<div class="grid cols3">${list.map(serviceCard).join('')}</div>`:empty('未找到对应功能','请输入功能名称，或通过咨询留言提交问题。',btn('咨询留言','consult','','primary'))}`;}
function serviceDetail(id){const s=allServices.find(x=>x.id===id);if(!s)return notFound();if(!canViewService(state.role,s))return accessDenied(s.name,'该入口仅面向馆员，请选择相应身份。');if(s.originalLink||s.externalUrl)return externalServiceDetail(s);const target={spaces:'spaces',help:'help',courses:'courses',discover:'discover'}[s.route];return `<div class="breadcrumb">${link('图书馆服务','services')} / ${esc(s.category)}</div>${head(esc(s.name),s.description)}<div class="detail-grid"><article class="card detail-content">${badge(s.depth)}<h2>服务内容</h2><p>${esc(s.description)}</p><h2>办理方式</h2><p>外部业务需要按服务提供方的资格、材料与登录要求办理。本站的申请登记和处理记录保存在当前浏览器。</p><div class="actions"><a href="${esc(s.sourceUrl||referenceUrl)}" target="_blank" rel="noopener noreferrer" class="text-link">查看服务网站 ↗</a></div></article><aside class="card side-card"><h3>服务办理</h3>${s.route==='request'?btn('提交文献申请','request','','primary'):s.route==='subscribe'?btn('保存订阅意向','subscribe',s.name,'primary'):target?link('打开功能 →',target,'btn primary'):btn('咨询此项服务','request-service',s.id,'primary')}${link('查看申请进度 →','workspace')}<p class="aside-note">正式办理结果以服务提供方记录为准。</p></aside></div>`;}
function consultationPage(){return `${head('咨询留言','提交问题，馆员受理后可查看回复。')}<div class="card"><div class="actions">${btn('咨询留言','consult','','primary')}${link('咨询反馈 →','workspace','btn')}</div></div>`;}
function externalServiceDetail(s){const o=s.originalLink;const url=s.externalUrl;const localAction=s.id==='original-consult'?btn('咨询留言','consult','','soft'):s.route==='request'?btn('馆际互借与文献传递','request','','soft'):s.target&&!s.target.startsWith('service/')?link(s.name+'',s.target,'btn soft'):'';return `<div class="breadcrumb">${link('图书馆服务','services')} / ${esc(s.category)}</div>${head(esc(s.name),o?.access||'打开对应的服务网站。')}<div class="card detail-content">${badge(url?'外部服务':o?.kind==='content'?'服务说明':'暂未开放',url?'green':'gray')}${url?`<div class="actions"><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">打开${esc(s.name)} ↗</a></div><p class="original-url">${esc(url)}</p><p>服务在新窗口打开，账号与访问权限由服务提供方认证。</p>`:o?.image?`<p>请使用微信扫码预约，或使用南京大学 APP 预约。</p><figure class="reservation-qr"><a href="${esc(o.image)}" target="_blank" rel="noopener noreferrer" aria-label="查看座位预约二维码大图"><img class="original-qr" src="${esc(o.image)}" alt="座位预约二维码" width="400" height="400"></a><p data-qr-error class="notice hidden" role="status">二维码暂时无法加载。请使用南京大学 APP 预约，或通过下方服务网站查看。</p></figure><p class="count">预约结果以官方系统为准。</p>`:s.name==='图书捐赠'?donationInstructions.map(p=>'<p>'+esc(p)+'</p>').join(''):'<p>该项服务暂未开放，请通过咨询留言了解详情。</p>'}<div class="actions">${localAction}<a class="text-link" href="${esc(o?.sourceUrl||s.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看服务网站 ↗</a></div>${localAction?'<p class="count">本站的资料与申请记录保存在当前浏览器；正式办理请使用官方入口。</p>':''}</div>`;}
function research(){const tab=params.get('tab')||'projects',ps=ownProjects();return head('科研服务','管理研学助手、文献、阅读笔记、综述矩阵和开题提纲。',btn('研学助手','new-project','','primary'))+`<div class="research-layout"><aside class="sidebar">${[['folder','研学助手','research'],['star','我的文献收藏','research?tab=favorites'],['book','课程文献中心','courses'],['grid','AI服务','tools'],['layers','选刊参考','research?tab=journals']].filter(([,name])=>name!=='课程文献中心'||canCreateCourse(state.role)).map(([i,t,r])=>`<a href="#${r}" class="${r===(tab==='projects'?'research':'research?tab='+tab)?'active':''}">${icon(i)} ${t}</a>`).join('')}<div class="split-line"></div><p class="subheading">文献整理步骤</p><p class="count">主题检索 → 文献夹 → 阅读笔记 → 综述矩阵 → 开题提纲</p></aside><div>${tab==='favorites'?`<div class="section-head"><h2>我的文献收藏</h2>${link('继续找资源 →','discover')}</div>${favorites().length?favorites().map(getResource).filter(Boolean).map(resourceCard).join(''):empty('收藏夹还是空的','从文献服务中收藏感兴趣的文献。',link('查找资源','discover','btn primary'))}`:tab==='journals'?`<div class="card"><h2>推荐期刊</h2><p style="margin-top:12px">按研究主题查找期刊，并在期刊官网核对范围、投稿要求与出版信息。</p><div class="actions"><a class="btn soft" href="https://doaj.org/search/journals" target="_blank" rel="noopener noreferrer">开放获取期刊目录 ↗</a><a class="btn" href="https://mjl.clarivate.com/" target="_blank" rel="noopener noreferrer">期刊目录查询 ↗</a></div></div>`:`<div class="section-head"><h2>研学助手</h2><span class="count">${ps.length} 个项目</span></div>${ps.length?`<div class="grid cols2">${ps.map(p=>`<a href="#project/${p.id}" class="card project-card">${icon('folder')}<h3 style="margin-top:16px">${esc(p.title)}</h3><p>${esc(p.question||'未填写研究问题')}</p><span class="count">${p.refs.length} 篇文献 · ${p.notes.length} 条笔记</span></a>`).join('')}</div>`:empty('从一个问题开始','创建项目，整理你的第一组研究资料。',btn('研学助手','new-project','','primary'))}<div class="card section"><h3>研究工具</h3><div class="guide-grid" style="margin-top:20px">${[['阅读笔记','摘录、页码和读后思考，保留信息上下文。'],['文献综述矩阵','手动对比问题、材料、方法与观点。'],['开题提纲填写','把你的输入整理为提纲，提示未填写部分。'],['引用导出','字段完整性提示，导出文本或 BibTeX。']].map(([t,d])=>`<div class="guide-item"><strong>${t}</strong><p>${d}</p></div>`).join('')}</div></div>`}</div></div>`;}
function projectPage(id){const p=state.projects.find(p=>p.id===id&&p.owner===state.role);if(!p)return empty('当前角色无法访问该项目','请切换项目所属身份，或建立自己的项目。',link('回到研究工作台','research','btn primary'));const tab=params.get('tab')||'refs',refs=p.refs.map(getResource).filter(Boolean);const tabs=[['refs','文献夹'],['notes','阅读笔记'],['matrix','综述矩阵'],['outline','开题提纲'],['citations','引用导出'],['knowledge','搜索项目文献与笔记']];return `<div class="breadcrumb">${link('科研服务','research')} / 研学助手</div>${head(esc(p.title),esc(p.question),btn('编辑项目信息','edit-project',p.id))}<div class="tabs">${tabs.map(([k,v])=>link(v,`project/${id}?tab=${k}`,tab===k?'active':'')).join('')}</div>${tab==='refs'?`<div class="section-head"><h2>项目文献 · ${refs.length}</h2>${link('查找并加入文献 →','discover')}</div>${refs.length?refs.map(r=>`<div>${resourceCard(r)}<div style="text-align:right;margin:-4px 0 16px">${btn('从本项目移除','remove-ref',`${p.id}|${r.id}`,'small')}</div></div>`).join(''):empty('文献夹还是空的','在文献服务中选择“加入文献夹”。',link('查找资源','discover','btn primary'))}`:tab==='notes'?`<div class="section-head"><h2>阅读笔记</h2>${btn('新建阅读笔记','new-note',p.id,'primary')}</div>${p.notes.length?p.notes.map(n=>`<article class="note"><div class="row-wrap"><h3>${esc(n.title)}</h3>${badge('页码 '+n.page,'gray')}</div><p style="margin-top:6px">${esc(getResource(n.resourceId)?.title||'项目笔记')} · ${esc(n.time)}</p><blockquote>${esc(n.quote)}</blockquote><p style="white-space:pre-wrap;color:#77684f">${esc(n.thought)}</p><div class="actions">${btn('编辑','edit-note',`${p.id}|${n.id}`,'small')}${btn('删除','delete-note',`${p.id}|${n.id}`,'small')}</div></article>`).join(''):empty('记下一次有价值的阅读','笔记关联文献、摘录和页码，记录你自己的思考。',btn('写一条笔记','new-note',p.id,'primary'))}`:tab==='matrix'?`<div class="section-head"><h2>文献综述矩阵</h2>${btn('导出 CSV','export-matrix',p.id,'small')}</div><div class="notice">逐项填写你的比较与判断。此工具不会自动生成综述，也不会推断未读文献的观点。</div>${refs.length?`<form id="matrix-form" data-project="${id}"><div class="card table-wrap"><table><thead><tr><th>文献</th>${['研究问题','材料','方法','核心观点','待核对'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${refs.map(r=>`<tr><td>${esc(r.title)}</td>${['question','material','method','argument','check'].map(k=>`<td><textarea name="${r.id}_${k}" aria-label="${esc(r.title)} ${{question:'研究问题',material:'材料',method:'方法',argument:'核心观点',check:'待核对'}[k]}" maxlength="3000" placeholder="手动填写…">${esc(p.matrix[r.id]?.[k]||'')}</textarea></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn primary">保存矩阵</button><span class="count">编辑后请保存</span></div></form>`:empty('先加入需要比较的文献','矩阵的每一行对应文献夹中的一篇文献。',link('查找文献','discover','btn primary'))}`:tab==='outline'?`<div class="detail-grid"><form id="outline-form" data-project="${id}" class="card form-grid"><h2>开题提纲填写</h2><p class="count">由你填写，平台整理结构并检查遗漏。</p>${Object.entries(outlineFields).map(([k,v])=>area(v,k,p.outline[k]||'',false)).join('')}<button class="btn primary">保存并更新提纲</button></form><aside class="card side-card"><h3>完整性检查</h3><p class="aside-note">已填写 ${Object.keys(outlineFields).filter(k=>p.outline[k]?.trim()).length} / 7 项</p><div class="notice">${Object.entries(outlineFields).filter(([k])=>!p.outline[k]?.trim()).map(([,v])=>`待补充：${v}`).join('<br>')||'七项均已填写，请自行核对内容与证据。'}</div>${btn('导出开题提纲','export-outline',id,'primary')}<p class="aside-note">导出的是可编辑 Markdown 提纲，不是自动生成的开题报告。</p></aside></div>`:tab==='citations'?`<div class="card"><div class="section-head"><h2>引用导出</h2><div class="row-wrap">${btn('导出文本','export-citations',id,'small')}${btn('导出 BibTeX','export-bib',id,'small')}</div></div><div class="notice warning">引用按已登记的原文题名与作者整理，使用前请核对来源页面及发表版本。</div>${refs.length?`<pre class="pre">${esc(refs.map((r,i)=>`[${i+1}] ${citation(r)}`).join('\n\n'))}</pre>`:empty('还没有引用记录','向文献夹添加资料后导出引用。')}</div>`:knowledgeProject(p)}`;}
function knowledgeProject(p){const q=params.get('q')||'';const hits=[...p.refs.map(getResource).filter(Boolean).map(r=>({title:r.title,text:r.tags,kind:'文献'})),...p.notes.map(n=>({title:n.title,text:n.quote+' '+n.thought,kind:'笔记'}))].filter(x=>`${x.title} ${x.text}`.includes(q));return `<div class="card"><h2>我的研究资料库</h2><form id="project-search" data-project="${p.id}" class="toolbar"><input name="q" aria-label="搜索项目资料" placeholder="在本项目文献与笔记中匹配关键词" value="${esc(q)}"><button class="btn primary">检索资料</button></form><p class="count">关键词检索，仅在你已保存的资料中匹配，不提供生成式问答。</p>${hits.length?hits.map(h=>`<div class="list-row"><div class="grow"><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p></div>${badge(h.kind,'gray')}</div>`).join(''):empty('未找到匹配资料','尝试其他关键词，或先保存文献与阅读笔记。')}</div>`;}
function coursesPage(){if(!canCreateCourse(state.role))return accessDenied('课程文献中心','课程书单创建和补充请求由教职工发起；馆员请在咨询反馈中处理课程工单。');const cs=state.courses.filter(c=>c.owner===state.role);return head('课程文献中心','建立课程文献中心、提交补充请求并查看馆员回复。',state.role==='teacher'?btn('创建课程文献中心','new-course','','primary'):'')+(state.role!=='teacher'?`<div class="notice warning">当前为${roles[state.role]}身份。建立书单与发起补充请求需要切换“教职工”；馆员请到工作台受理课程请求。</div><div class="card"><h2>课程文献中心协作</h2><div class="guide-grid section">${[['1 · 教职工建书单','创建课程，添加文献记录和补充方向。'],['2 · 发起补充请求','请求与课程文献中心建立明确关联。'],['3 · 馆员受理回复','补充材料、获取路径或处理意见。'],['4 · 教职工查看结果','结果回到原申请与课程文献中心。']].map(([t,d])=>`<div class="guide-item"><strong>${t}</strong><p>${d}</p></div>`).join('')}</div></div>`:cs.length?cs.map(c=>`<article class="card section"><div class="panel-head"><div>${badge('课程文献中心','green')}<h2 style="margin-top:12px">${esc(c.title)}</h2><p style="font-size:13px;margin-top:10px">${esc(c.description)}</p></div><div class="row-wrap">${btn('添加书目','course-add',c.id)}${btn('申请馆员补充','course-request',c.id,'primary')}</div></div>${c.refs.length?c.refs.map(getResource).filter(Boolean).map(r=>`<div class="list-row">${icon('book')}<div class="grow"><h3>${esc(r.title)}</h3><p>${esc(r.author)} · ${r.year}</p></div>${btn('移除','course-remove',`${c.id}|${r.id}`,'small')}</div>`).join(''):empty('书单暂时没有书目','添加公开文献，或直接说明需要补充的方向。')}<div class="section-head" style="margin-top:24px"><h3>关联补充请求</h3></div>${ticketRows(state.tickets.filter(t=>t.courseId===c.id))}</article>`).join(''):empty('创建你的第一份课程文献中心','添加课程信息，选择书目，与馆员协作补充资料。',btn('创建课程文献中心','new-course','','primary')));}
function toolsPage(){const q=params.get('q')||'';return head('AI服务','按研究任务查找工具，前往服务网站使用。')+`<form id="tool-search" class="toolbar"><input name="q" aria-label="搜索科研工具" value="${esc(q)}" placeholder="搜索工具或研究阶段"><button class="btn primary">搜索工具</button></form><div class="notice warning">外部工具需要独立账号，费用、地区可用性与机构授权以提供方说明为准。</div>${toolGroups.filter(g=>!q||g.name.includes(q)||g.tools.some(([n])=>n.toLowerCase().includes(q.toLowerCase()))).map(g=>`<section class="card section"><h2>${g.name}</h2><p class="count" style="margin:8px 0 15px">外部服务 · 可能需要独立账号、订阅或机构授权</p>${g.tools.filter(([n])=>!q||g.name.includes(q)||n.toLowerCase().includes(q.toLowerCase())).map(([n,u])=>`<div class="tool-row"><div><span>${n}</span><br><small>使用条件与费用以官方页面为准</small></div><a class="btn small" href="${u}" rel="noopener noreferrer" target="_blank">访问外部网站 ↗</a></div>`).join('')}</section>`).join('')||empty('没有匹配工具','换一个关键词或查看全部工具。')}`;}
function spacesPage(){const tab=params.get('tab')||'rooms';return head('空间服务','查询官方预约入口，管理个人时段需求。')+`<div class="tabs">${link('座位预约','spaces?tab=seats',tab==='seats'?'active':'')}${link('研讨间预约（校内IP）','spaces?tab=rooms',tab==='rooms'?'active':'')}${link('讲座&活动','spaces?tab=events',tab==='events'?'active':'')}${link('开放时间','spaces?tab=hours',tab==='hours'?'active':'')}${link('我的预约','workspace?tab=reservations')}</div>`+(tab==='hours'?`<div class="card"><h2>开放时间</h2><p style="margin:16px 0">各馆舍开放安排以图书馆公告为准。</p>${originalLink('开放时间','services','btn primary','查看开放时间')}</div>`:tab==='events'?empty('暂无已发布活动','讲座与活动安排请关注图书馆公告。',originalLink('资源动态','services','btn soft','查看图书馆公告')):`<div class="notice">本站登记时段需求并检查当前浏览器内的冲突。实际预约请通过官方系统完成。</div><div class="actions" style="margin-bottom:22px">${tab==='seats'?link('打开座位预约入口 →','service/original-'+encodeURIComponent('座位预约'),'btn primary'):originalLink('研讨间预约（校内IP）','services','btn primary','打开研讨间预约入口')}</div><div class="grid cols3">${[['研讨间 A','4—6 人 · 讨论 / 小组协作',''],['研讨间 B','2—4 人 · 研读 / 讨论','b'],['专注座位 01','1 人 · 安静阅读 / 个人学习','c']].filter(([n])=>tab==='seats'?n.startsWith('专注'):!n.startsWith('专注')).map(([n,d,c])=>`<article class="card"><div class="room-art ${c}" aria-hidden="true"></div>${badge('时段需求登记','gray')}<h2 style="margin-top:14px">${n}</h2><p style="font-size:12px;margin:10px 0 18px">${d}</p>${canReserve(state.role)?btn('选择日期与时段','reserve',n,'primary'):link('查看官方预约入口 →','service/original-'+encodeURIComponent('座位预约'),'btn soft')}</article>`).join('')}</div><section class="card section"><h2>已登记时段</h2><p class="count" style="margin-top:7px">当前浏览器的时段记录。</p>${state.reservations.filter(r=>r.status==='已登记').map(r=>`<div class="list-row">${icon('calendar')}<div class="grow"><h3>${esc(r.room)}</h3><p>${r.date} · ${r.start}—${r.end}</p></div>${badge(roles[r.owner]+'登记','gray')}</div>`).join('')||'<p class="todo-empty">暂无时段登记。</p>'}</section>`);}
function reservationsView(){const list=myReservations();return `<div class="section-head"><h2>我的空间预约</h2>${link('登记新时段 →','spaces')}</div>${list.length?list.map(b=>`<article class="card list-row" style="margin-bottom:12px"><div class="event-date">${b.date.slice(8)}</div><div class="grow"><h3>${esc(b.room)}</h3><p>${b.date} · ${b.start}—${b.end}</p></div>${badge(b.status,['已登记','已预约'].includes(b.status)?'green':'gray')}${['已登记','已预约'].includes(b.status)?btn('取消预约','cancel-reservation',b.id,'small'):''}</article>`).join(''):empty('还没有预约','选择适合你的空间，登记所需时段，并在这里查看或取消。',link('查看空间','spaces','btn primary'))}`;}
function workspace(){const staff=state.role==='librarian',manager=false,tab=params.get('tab')||'tickets',list=staff||manager?state.tickets:myTickets(),status=params.get('status')||'全部',shown=list.filter(t=>status==='全部'||t.status===status);return `<section class="workspace-intro"><span class="avatar">${roles[state.role][0]}</span><div><h2>${staff?'馆员服务台':manager?'服务运营观察':roles[state.role]+'工作台'}</h2><p>${staff?'受理申请、补充材料、回复处理结果。':manager?'从操作记录观察需求、积压与处理结果。':'查看申请、预约、收藏和研学助手。'}</p></div></section><div class="stats">${[[list.filter(t=>t.status==='待受理').length,'待受理申请'],[list.filter(t=>t.status==='待补材料').length,'待补材料'],[list.filter(t=>t.status==='已回复').length,'已回复'],[list.filter(t=>t.status==='已完成').length,'已完成']].map(([n,t])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="tabs">${link(staff?'馆员工单':manager?'运营总览':'我的申请','workspace',tab==='tickets'?'active':'')}${!staff&&!manager?link('我的预约','workspace?tab=reservations',tab==='reservations'?'active':'')+link('我的收藏','research?tab=favorites')+link('研学助手','research'):''}${link('订阅与报名','workspace?tab=subscriptions',tab==='subscriptions'?'active':'')}</div>${tab==='reservations'?reservationsView():tab==='subscriptions'?`<div class="card"><h2>订阅意向</h2><div class="notice">仅保存意向，不执行定时检索、邮件或消息推送。</div>${state.subscriptions.filter(s=>s.owner===state.role).map(s=>`<div class="list-row"><div class="grow"><h3>${esc(s.title)}</h3><p>${esc(s.type)}</p></div>${btn('移除','unsubscribe',s.id,'small')}</div>`).join('')||'<p>暂无订阅意向。</p>'}<div class="actions">${btn('新增主题订阅','subscribe','检索订阅','soft')}</div><div class="split-line"></div><h2>活动报名</h2>${state.registrations.filter(r=>r.owner===state.role).map(r=>`<div class="list-row"><div class="grow"><h3>${events.find(e=>e.id===r.eventId)?.title}</h3></div>${btn('取消','register',r.eventId,'small')}</div>`).join('')||'<p style="margin-top:14px">暂无报名。</p>'}</div>`:`${manager?`<div class="notice">所有指标来自本浏览器的操作记录，无真实运行数据。管理角色只读，馆员负责受理与回复。</div>`:''}<div class="section-head"><h2>${staff?'服务工单':manager?'申请与积压':'我的服务申请'}</h2>${!staff&&!manager?btn('咨询留言','consult','','primary'):badge('本地记录','gray')}</div><div class="pills">${['全部','待受理','处理中','待补材料','已回复','已完成'].map(s=>link(s,`workspace?status=${encodeURIComponent(s)}`,`pill ${s===status?'active':''}`)).join('')}</div>${shown.length?`<div class="card table-wrap"><table><thead><tr><th>申请与编号</th><th>服务类型</th><th>提交身份</th><th>状态</th><th>处理</th></tr></thead><tbody>${shown.map(t=>`<tr><td><a class="text-link" href="#ticket/${t.id}">${esc(t.title)}</a><p class="count">${t.no}</p></td><td>${t.type}</td><td>${roles[t.owner]}</td><td>${badge(t.status,t.status==='待补材料'?'orange':t.status==='已完成'?'green':'')}</td><td>${link(staff?'查看与处理 →':'查看记录 →','ticket/'+t.id)}</td></tr>`).join('')}</tbody></table></div>`:empty(staff?'当前没有待处理工单':'这里还没有申请','提交申请后，可在这里查看状态与处理记录。',btn('查看两条操作步骤','guide','','soft'))}${manager?`<section class="card section"><h2>需求类型分布</h2>${[...new Set(state.tickets.map(t=>t.type))].map(type=>`<div style="margin-top:18px"><span class="count">${esc(type)} · ${state.tickets.filter(t=>t.type===type).length} 项</span><div class="meter"><span style="width:${state.tickets.filter(t=>t.type===type).length/Math.max(1,state.tickets.length)*100}%"></span></div></div>`).join('')||'<p class="count" style="margin-top:15px">提交申请后将出现分布。</p>'}</section>`:''}`}`;}
function ticketPage(id){const t=state.tickets.find(t=>t.id===id&&canViewTicket(state.role,t));if(!t)return empty('无法访问此申请','请切换申请所属身份或馆员身份。',link('返回工作台','workspace','btn primary'));const staff=state.role==='librarian',owner=t.owner===state.role;return `<div class="breadcrumb">${link('咨询反馈','workspace')} / ${t.no}</div>${head(esc(t.title),`${t.no} · ${t.type} · ${roles[t.owner]}提交`)}<div class="detail-grid"><article class="card"><div class="panel-head"><h2>处理记录</h2>${badge(t.status,t.status==='待补材料'?'orange':t.status==='已完成'?'green':'')}</div>${t.courseId?`<div class="notice">关联课程：${esc(state.courses.find(c=>c.id===t.courseId)?.title||'课程文献中心')}。回复将同时显示在课程文献中心的关联请求中。</div>`:''}<div class="timeline">${t.history.map(h=>`<div class="timeline-item"><h3>${h.action} · ${roles[h.by]}</h3><small>${esc(h.time)}</small>${h.text?`<p>${esc(h.text)}</p>`:''}</div>`).join('')}</div></article><aside class="card side-card"><h3>${staff?'馆员处理':'下一步'}</h3><p class="aside-note">${t.assignee?`受理人：${t.assignee}`:'当前尚未受理。'}<br>处理记录保存在当前浏览器。</p>${staff&&t.status==='待受理'?btn('受理此申请','ticket-accept',t.id,'primary'):''}${staff&&t.status==='处理中'?btn('要求补充材料','ticket-need',t.id)+btn('回复处理结果','ticket-reply',t.id,'primary'):''}${owner&&t.status==='待补材料'?btn('补充材料','ticket-supplement',t.id,'primary'):''}${owner&&t.status==='已回复'?btn('确认已解决','ticket-confirm',t.id,'primary')+btn('继续提问','ticket-reopen',t.id):''}${t.status==='已完成'?`<div class="notice">本次申请已完成，可在处理记录中回看全部回应。</div>`:''}${!staff&&!owner?'<div class="notice">当前身份无处理权限。</div>':''}${btn('导出处理记录','export-ticket',t.id)}${t.courseId&&owner?link('返回课程文献中心 →','courses'):''}</aside></div>`;}
function helpPage(){const q=params.get('q')||'',hits=knowledge.filter(k=>`${k.title} ${k.tags} ${k.answer}`.includes(q));return head('AI馆员','查询馆务指引或提交咨询留言。具体服务规则以官方说明为准。',btn('咨询留言','consult','','primary'))+`<form id="help-search" class="toolbar"><input name="q" aria-label="搜索AI馆员" value="${esc(q)}" placeholder="例如：校外访问、全文、预约、校友"><button class="btn primary">${icon('search')} 查找帮助</button></form><div class="detail-grid"><div class="card knowledge"><h2>常见问题 <span class="count">${hits.length} 条</span></h2>${hits.length?hits.map(k=>`<details ${q?'open':''}><summary>${k.title}</summary><p>${k.answer}</p><small>依据：${k.source} · 更新于 2026-10-28 · 维护：服务台</small>${k.action==='request'?btn('提交人工求助','request',q,'small'):link('进入相关任务 →',k.action)}</details>`).join(''):empty('知识库中没有找到答案','可提交咨询留言，由馆员处理。',btn('咨询留言','consult',q,'primary'))}</div><aside class="card side-card"><h3>咨询留言</h3><p class="aside-note">提供问题场景、资源名称和已尝试的方法，可以帮助馆员更快理解需求。</p>${btn('馆际互借与文献传递','request','','primary')}${link('查看我的申请 →','workspace')}<div class="split-line"></div><h3>第一次使用？</h3><p class="aside-note">右上角切换在校生、教职工、校友/社会公众和馆员。外部系统需要单独登录；这里的身份选择用于本浏览器内的资料和工作台管理。</p>${btn('使用帮助','guide','','soft')}</aside></div>`;}
function notFound(){return empty('这个页面暂时找不到','链接可能有误，请回到首页继续。',link('返回首页','home','btn primary'));}
function render(){const [path,query='']=(location.hash.slice(1)||'home').split('?');parts=path.split('/');route=parts[0];params=new URLSearchParams(query);const pages={home,discover,research,services:serviceList,spaces:spacesPage,workspace,courses:coursesPage,tools:toolsPage,help:helpPage,usage:()=>usagePage(params.get('role'),state.role,roles,esc,params.get('step')),service:()=>serviceDetail(parts[1]),resource:()=>resourceDetail(parts[1]),project:()=>projectPage(parts[1]),ticket:()=>ticketPage(parts[1])};try{$('#app').innerHTML=shell((pages[route]||notFound)());}catch(e){$('#app').innerHTML=shell(empty('页面数据暂时无法读取','请导出本地数据后重置，或返回首页。',btn('清空本地数据','reset','','primary')));console.error(e);}document.title=`${({usage:'使用帮助',home:'首页',discover:'文献服务',research:'科研服务',services:'图书馆服务',spaces:'空间服务',workspace:'咨询反馈',courses:'课程文献中心',tools:'科研工具',help:'AI馆员',project:'研学助手',ticket:'申请进度',service:'服务详情',resource:'资源详情'})[route]||'智慧图书馆'} · 南京大学图书馆`;}
function requestModal(type='馆际互借与文献传递',title='',body='',courseId=''){if(type==='课程书单补充'&&state.role!=='teacher')throw Error('请切换教职工身份');modal(type==='课程书单补充'?'课程文献中心补充请求':'提交'+type,'申请与处理记录保存在当前浏览器，可在咨询反馈中查看。',`<input type="hidden" name="type" value="${esc(type)}"><input type="hidden" name="courseId" value="${esc(courseId)}">${field('申请标题','title',title)}${area('需求说明与材料（请勿填写真实敏感信息）','body',body)}<p class="field-help">当前申请人：${roles[state.role]}账号。文献请注明作者、年份与来源。</p>`,'request-form');}
function noteModal(p,rid='',n=null){if(!p)throw Error('请先研学助手并加入文献');modal(n?'编辑阅读笔记':'新建阅读笔记','在记录旁保留摘录、页码和自己的判断。',`<label>关联文献<select name="resourceId">${opts([['','项目综合笔记'],...p.refs.map(getResource).filter(Boolean).map(r=>[r.id,r.title])],n?.resourceId||rid)}</select></label>${field('笔记标题','title',n?.title||'')}${field('页码 / 位置','page',n?.page||'')}${area('摘录或内容记录','quote',n?.quote||'')}${area('我的思考','thought',n?.thought||'',false)}`,'note-form',`data-project="${p.id}" data-note="${n?.id||''}"`);}
function guide(){if($('#modal').open)$('#modal').close();go('usage');}
document.addEventListener('error',e=>{const img=e.target;if(img?.classList?.contains('original-qr')){img.hidden=true;img.closest('.reservation-qr')?.querySelector('[data-qr-error]')?.classList.remove('hidden');}},true);

document.addEventListener('change',e=>{if(e.target.id==='role'){state.role=e.target.value;scope=state.role==='alumni'?'services':'resources';save();if($('#modal').open)$('#modal').close();render();toast('已切换为'+roles[state.role]+'身份');}});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id||'';try{requireAction(state.role,a);if(a==='close'){$('#modal').close();return;}if(a==='scope'){scope=id;render();return;}if(a==='guide'){guide();return;}if(a==='favorite'){const f=state.favorites[state.role]??=[];const i=f.indexOf(id);if(i<0)f.push(id);else f.splice(i,1);save();render();toast(i<0?'已加入我的收藏':'已取消收藏');return;}if(a==='consult'){requestModal('咨询留言',id||'','');return;}if(a==='request'){requestModal('馆际互借与文献传递',id||'', '');return;}if(a==='request-service'){const s=allServices.find(x=>x.id===id);requestModal('咨询留言',s.name+'服务咨询','我希望了解此项服务的办理条件。');return;}if(a==='request-resource'){const r=getResource(id);requestModal('馆际互借与文献传递',r.title,`题名：${r.title}\n作者：${r.author}\n年份：${r.year}\n来源：${r.source}\n已尝试的渠道：\n希望获取：`);return;}if(a==='new-project'||a==='edit-project'){const p=state.projects.find(x=>x.id===id&&x.owner===state.role);modal(p?'编辑研学助手':'研学助手','项目资料仅属于当前身份。',field('项目名称','title',p?.title||'')+area('研究问题','question',p?.question||'',false),'project-form',`data-project="${p?.id||''}"`);return;}if(a==='add-ref'||a==='note-resource'){const ps=ownProjects();if(!ps.length){modal('先建立一个研学助手','创建后会自动将这篇文献加入文献夹。',`<input type="hidden" name="resourceId" value="${id}"><input type="hidden" name="next" value="${a}">${field('项目名称','title')}${area('研究问题','question','',false)}`,'project-form');return;}modal(a==='add-ref'?'加入文献夹':'选择笔记所属项目','选择项目后可继续整理。',`<input type="hidden" name="resourceId" value="${id}"><input type="hidden" name="next" value="${a}"><label>研学助手<select name="projectId">${opts(ps.map(p=>[p.id,p.title]),ps[0].id)}</select></label>`,'add-ref-form');return;}if(a==='remove-ref'){const [pid,rid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);if(!p)throw Error('没有权限');p.refs=p.refs.filter(x=>x!==rid);save();render();toast('已从文献夹移除，笔记仍保留');return;}if(['new-note','edit-note','note-resource'].includes(a)){const [pid,nid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);noteModal(p,'',p?.notes.find(n=>n.id===nid));return;}if(a==='delete-note'){const [pid,nid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);if(!p)throw Error('无权操作');modal('删除这条笔记？','删除后无法恢复，请确认已保存所需内容。',btn('确认删除','confirm-delete-note',id,'danger'));return;}if(a==='confirm-delete-note'){const [pid,nid]=id.split('|'),p=state.projects.find(p=>p.id===pid&&p.owner===state.role);p.notes=p.notes.filter(n=>n.id!==nid);save();$('#modal').close();render();return;}
if(a==='cite'){const r=getResource(id);modal('引用导出与字段核对','按来源记录整理书目信息，使用前请核对发表版本。',`<pre class="pre">${esc(citation(r))}</pre>${btn('下载引用文本','export-one',id,'primary')}`);return;}if(a==='export-one'){download('文献引用.txt',''+citation(getResource(id)));return;}if(a.startsWith('export-')){const p=state.projects.find(p=>p.id===id&&p.owner===state.role),refs=p?.refs.map(getResource).filter(Boolean)||[];if(a==='export-state')download('智慧图书馆-本地数据.json',JSON.stringify(state,null,2),'application/json');if(a==='export-catalog')download('服务目录.csv','\uFEFF'+csv([['名称','分类','来源','服务状态','说明','来源入口','实际跳转地址','访问条件'],...allServices.map(s=>[s.name,s.category,s.source,s.depth,s.description,s.sourceUrl,s.externalUrl||'',s.originalLink?.access||''])]),'text/csv;charset=utf-8');if(a==='export-outline'&&p)download(p.title+'-开题提纲.md',outline(p.outline));if(a==='export-matrix'&&p)download(p.title+'-综述矩阵.csv','\uFEFF'+csv([['文献','研究问题','材料','方法','核心观点','待核对'],...refs.map(r=>[r.title,...['question','material','method','argument','check'].map(k=>p.matrix[r.id]?.[k]||'')])]),'text/csv;charset=utf-8');if((a==='export-citations'||a==='export-bib')&&p)download(p.title+(a==='export-bib'?'.bib':'-引用.txt'),''+refs.map(r=>citation(r,a==='export-bib'?'bib':'gb')).join('\n\n'));if(a==='export-ticket'){const t=state.tickets.find(t=>t.id===id&&(t.owner===state.role||['librarian','manager'].includes(state.role)));if(t)download(t.no+'-处理记录.txt',`${t.title}\n${t.status}\n\n`+t.history.map(h=>`${h.time} ${roles[h.by]} ${h.action}\n${h.text}`).join('\n\n'));}return;}
if(a==='new-course'){if(state.role!=='teacher')throw Error('请切换教职工身份');modal('创建课程文献中心','建立课程与书目，再向馆员提出补充方向。',field('课程名称','title')+area('课程简介 / 学期','description','',false),'course-form');return;}if(a==='course-add'){const c=state.courses.find(c=>c.id===id&&c.owner===state.role);if(!c)throw Error('无权操作');modal('向课程添加书目','可多选公开文献。正式书单需核对实际书目信息。',resources.map(r=>`<label style="display:flex;align-items:center;gap:12px"><input type="checkbox" name="refs" value="${r.id}" ${c.refs.includes(r.id)?'checked':''}>${esc(r.title)}</label>`).join(''),'course-add-form',`data-course="${id}"`);return;}if(a==='course-remove'){const [cid,rid]=id.split('|'),c=state.courses.find(c=>c.id===cid&&c.owner===state.role);if(!c)throw Error('没有权限');c.refs=c.refs.filter(x=>x!==rid);save();render();return;}if(a==='course-request'){const c=state.courses.find(c=>c.id===id&&c.owner===state.role);if(!c)throw Error('没有权限');requestModal('课程书单补充',c.title+' · 书单补充',`课程：${c.title}\n已有书目：${c.refs.map(r=>getResource(r)?.title).join('、')||'暂无'}\n希望补充的方向：`,c.id);return;}
if(a==='reserve'){modal('预约'+esc(id),'可登记时段 08:00—22:00；重叠会提示冲突。',`<input type="hidden" name="room" value="${esc(id)}">${field('日期','date',today(),'date')}<div class="form-grid inline">${field('开始时间','start','09:00','time')}${field('结束时间','end','10:00','time')}</div><div class="notice">时段登记面向在校生与教职工；实际预约须通过官方系统。</div>`,'reservation-form');return;}if(a==='cancel-reservation'){cancelReservation(state,state.role,id);save();render();toast('预约已取消，时段已释放');return;}
if(a.startsWith('ticket-')){const action=a.slice(7);if(action==='accept'||action==='confirm'){transition(state,state.role,id,action);save();render();toast(action==='accept'?'已受理，请继续处理':'已确认解决');return;}const labels={need:'要求补充材料',reply:'回复处理结果',supplement:'补充材料',reopen:'继续提问'};modal(labels[action],'内容会保存到申请时间线，申请人和馆员均可查看。',`<input type="hidden" name="ticketId" value="${id}"><input type="hidden" name="action" value="${action}">${area('内容','text')}`,'transition-form');return;}
if(a==='subscribe'){modal('保存订阅意向','此不发送通知，只在工作台保存主题。',`<input type="hidden" name="type" value="${esc(id||'检索订阅')}">${field('期刊名称或主题检索式','title')}`,'subscribe-form');return;}if(a==='unsubscribe'){state.subscriptions=state.subscriptions.filter(s=>s.id!==id||s.owner!==state.role);save();render();return;}if(a==='register'){const i=state.registrations.findIndex(r=>r.eventId===id&&r.owner===state.role);if(i<0)state.registrations.push({eventId:id,owner:state.role});else state.registrations.splice(i,1);save();render();toast(i<0?'已保存报名':'已取消报名');return;}if(a==='reset'){modal('重置当前浏览器的本地数据？','这会清除当前浏览器的项目、申请与时段记录。请先导出备份。',`<div class="actions">${btn('先导出本地数据','export-state')}${btn('确认清空本地数据','confirm-reset','','danger')}</div>`);return;}if(a==='confirm-reset'){const role=state.role;state=initialState();state.role=role;save();$('#modal').close();go('home');render();toast('本地数据已清空');return;}
}catch(e){error(e);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd),submit=f.querySelector('button[type="submit"],button:not([type])');try{if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true');}if(f.id==='search-global'){const q=String(v.q||'').trim();if(q){state.searchHistory.unshift({q,scope,time:stamp()});state.searchHistory=state.searchHistory.slice(0,20);save();}go(`${scope==='resources'?'discover':scope==='services'?'services':'help'}?q=${encodeURIComponent(q)}`);return;}if(['resource-search','resource-filter','service-search','help-search','tool-search','project-search','journal-form'].includes(f.id)){const r={'resource-search':'discover','resource-filter':'discover','service-search':'services','help-search':'help','tool-search':'tools','project-search':`project/${f.dataset.project}?tab=knowledge`,'journal-form':'research?tab=journals'}[f.id];const q=new URLSearchParams(v);if(f.id==='service-search'&&params.get('source')==='reference')q.set('source','reference');if(f.id==='resource-filter'&&v.fav)q.set('fav','1');go(r+(r.includes('?')?'&':'?')+q);return;}
if(f.id==='request-form'){const t=createTicket(state,state.role,v);save();$('#modal').close();go('ticket/'+t.id);toast('申请已提交，可切换馆员处理');return;}if(f.id==='project-form'){let p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!v.title.trim())throw Error('请填写项目名称');if(p){p.title=v.title.trim();p.question=v.question.trim();}else{p={id:uid(),owner:state.role,title:v.title.trim(),question:v.question.trim(),refs:v.resourceId?[v.resourceId]:[],notes:[],matrix:{},outline:{}};state.projects.unshift(p);}save();$('#modal').close();if(v.next==='note-resource'){render();noteModal(p,v.resourceId);}else{go('project/'+p.id);toast('研学助手已保存');}return;}if(f.id==='add-ref-form'){const p=state.projects.find(p=>p.id===v.projectId&&p.owner===state.role);if(!p)throw Error('项目不存在');if(!p.refs.includes(v.resourceId))p.refs.push(v.resourceId);save();$('#modal').close();if(v.next==='note-resource')noteModal(p,v.resourceId);else toast('已加入文献夹');return;}if(f.id==='note-form'){const p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!p)throw Error('项目不存在');const n={...v,id:f.dataset.note||uid(),time:stamp()};if(f.dataset.note)p.notes=p.notes.map(x=>x.id===n.id?n:x);else p.notes.unshift(n);save();$('#modal').close();go(`project/${p.id}?tab=notes`);render();toast('阅读笔记已保存');return;}if(f.id==='matrix-form'){const p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!p)throw Error('项目不存在');for(const r of p.refs){p.matrix[r]??={};for(const k of ['question','material','method','argument','check'])p.matrix[r][k]=v[`${r}_${k}`]||'';}save();toast('综述矩阵已保存');return;}if(f.id==='outline-form'){const p=state.projects.find(p=>p.id===f.dataset.project&&p.owner===state.role);if(!p)throw Error('项目不存在');p.outline=v;save();render();toast('已保存并更新完整性检查');return;}if(f.id==='course-form'){if(state.role!=='teacher')throw Error('仅教职工可创建');if(!v.title.trim())throw Error('请填写课程名称');state.courses.unshift({id:uid(),owner:state.role,title:v.title.trim(),description:v.description,refs:[]});save();$('#modal').close();render();toast('课程文献中心已创建');return;}if(f.id==='course-add-form'){const c=state.courses.find(c=>c.id===f.dataset.course&&c.owner===state.role);if(!c)throw Error('无权操作');c.refs=fd.getAll('refs').filter(id=>getResource(id));save();$('#modal').close();render();toast('课程书目已更新');return;}if(f.id==='reservation-form'){reserve(state,state.role,v);save();$('#modal').close();go('workspace?tab=reservations');toast('时段登记已保存');return;}if(f.id==='transition-form'){transition(state,state.role,v.ticketId,v.action,v.text);save();$('#modal').close();render();toast('处理记录已更新');return;}if(f.id==='subscribe-form'){if(!v.title.trim())throw Error('请填写订阅主题');state.subscriptions.push({...v,id:uid(),owner:state.role});save();$('#modal').close();go('workspace?tab=subscriptions');toast('订阅意向已保存，未启用推送');return;}
}catch(e){error(e);}finally{if(submit){submit.disabled=false;submit.removeAttribute('aria-busy');}}});
function csv(rows){return rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY){try{const n=JSON.parse(e.newValue);if(n?.version===1){if($('#modal').open)$('#modal').close();state=migrateRoles(n);render();toast('已同步此浏览器另一标签页的操作记录');}}catch{}}});
render();

